def copy_matrix_gsl(source, destination):
    rows = len(source)
    cols = len(source[0])
    source_ptr = (ctypes.c_double * rows)()
    for i in range(rows):
        for j in range(cols):
            source_ptr[i * cols + j] = ctypes.c_double(source[i][j])

    destination_ptr = (ctypes.c_double * rows)()
    for i in range(rows):
        for j in range(cols):
            destination_ptr[i * cols + j] = ctypes.c_double(destination[i][j])

    gsl.gsl_matrix_memcpy(ctypes.byref(gsl.matrix_alloc(rows, cols)), ctypes.byref(gsl.matrix_from_pointer(source_ptr, rows, cols)))
    gsl.gsl_matrix_memcpy(ctypes.byref(gsl.matrix_alloc(rows, cols)), ctypes.byref(gsl.matrix_from_pointer(destination_ptr, rows, cols)))

    for i in range(rows):
        for j in range(cols):
            destination[i][j] = float(destination_ptr[i * cols + j])

    return destination

