import ctypes
import numpy as np

def compute_eigenvalues(A, B):
    if not isinstance(A, np.ndarray) or not isinstance(B, np.ndarray): raise ValueError('Inputs must be NumPy arrays')
    if A.dtype != 'complex' or B.dtype != 'complex': raise ValueError('Inputs must be complex type')
    if A.ndim != 2 or B.ndim != 2: raise ValueError('Inputs must be 2D matrices')
    if A.shape[0] != A.shape[1] or B.shape[0] != B.shape[1]: raise ValueError('Inputs must be square matrices')
    if A.shape != B.shape: raise ValueError('Matrices dimensions must match')

    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    def numpy_to_gsl_matrix_complex(np_array):
        rows, cols = np_array.shape
        data_type = np_array.dtype.type
        if data_type is not np.complex128:
            raise ValueError('Unsupported complex data type')
        gsl_matrix_complex = gsl.gsl_matrix_complex_alloc(rows, cols)
        for i in range(rows):
            for j in range(cols):
                gsl.gsl_matrix_complex_set(gsl_matrix_complex, i, j, ctypes.c_double(np_array[i, j].real), ctypes.c_double(np_array[i, j].imag))
        return gsl_matrix_complex

    def gsl_vector_to_numpy(gsl_vector, size):
        np_array = np.empty(size, dtype=np.complex128)
        for i in range(size):
            real = gsl.gsl_vector_get_real(gsl_vector, i)
            imag = gsl.gsl_vector_get_imag(gsl_vector, i)
            np_array[i] = complex(real, imag)
        return np_array

    A_gsl = numpy_to_gsl_matrix_complex(A)
    B_gsl = numpy_to_gsl_matrix_complex(B)

    eigenvalues = gsl.gsl_vector_alloc(A.shape[0])

    status = gsl.gsl_eigen_genherm(A_gsl, B_gsl, eigenvalues)
    if status != 0:
        raise RuntimeError('Failed to compute eigenvalues')

    result = gsl_vector_to_numpy(eigenvalues, A.shape[0])
    gsl.gsl_matrix_complex_free(A_gsl)
    gsl.gsl_matrix_complex_free(B_gsl)
    gsl.gsl_vector_free(eigenvalues)

    return result

