class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = matrix
        self.rows = len(matrix)
        self.cols = len(matrix[0])
        self.data = (ctypes.c_double * (self.rows * self.cols))()
        for i in range(self.rows):
            for j in range(self.cols):
                self.data[i * self.cols + j] = matrix[i][j]

    def find_minmax_indices(self):
        min_index = ctypes.c_size_t(0)
        max_index = ctypes.c_size_t(0)
        gsl.gsl_matrix_minmax_index.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_size_t, ctypes.c_size_t, ctypes.POINTER(ctypes.c_size_t), ctypes.POINTER(ctypes.c_size_t)]
        gsl.gsl_matrix_minmax_index.restype = None
        gsl.gsl_matrix_minmax_index(self.data, self.rows, self.cols, ctypes.byref(min_index), ctypes.byref(max_index))
