        self.vector = gsl.gsl_vector_alloc(self.size)
        for i in range(self.size):
            gsl.gsl_vector_set(self.vector, i, values[i])

    def manipulate_vector(self, increment):
        for i in range(self.size):
            value = gsl.gsl_vector_get(self.vector, i) + increment
            gsl.gsl_vector_set(self.vector, i, value)

    def get_values(self):
        result = [0] * self.size
        for i in range(self.size):
            result[i] = gsl.gsl_vector_get(self.vector, i)
        return result

