class GSLFunction:
    def __init__(self, func):
        self.func = func
        self.callback = self._callback

    def _callback(self, x, data):
        return self.func(x)

class GSLIntegrationWorkspace:
    def __init__(self):
        self.workspace = None

    def integrate(self, function, a, b, epsabs, epsrel, limit, key):
        from ctypes import c_double, POINTER, byref
        gsl_integration_qag = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so").gsl_integration_qag
        gsl_integration_qag.argtypes = [POINTER(GSLFunction), c_double, c_double, c_double, c_double, c_size_t, c_int, POINTER(ctypes.c_double), ctypes.POINTER(c_double)]
        result = ctypes.c_double()
        abserr = ctypes.c_double()
        gsl_integration_qag(byref(function), a, b, epsabs, epsrel, limit, key, byref(result), byref(abserr))
