import ctypes

class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = matrix
        self.size1 = matrix.shape[0]
        self.size2 = matrix.shape[1]

    def to_gsl_matrix(self):
        data_type = np.ctypeslib.ndpointer(dtype=np.double, ndim=2, flags='C_CONTIGUOUS')
        return ctypes.c_void_p(np.ascontiguousarray(self.matrix, dtype=np.double).ctypes.data_as(data_type))

class GSLVector:
    def __init__(self, vector):
        self.vector = vector
        self.size = vector.shape[0]

    def to_gsl_vector(self):
        data_type = np.ctypeslib.ndpointer(dtype=np.double, ndim=1, flags='C_CONTIGUOUS')
        return ctypes.c_void_p(np.ascontiguousarray(self.vector, dtype=np.double).ctypes.data_as(data_type))

