def create_gsl_matrix(rows, cols):
    matrix = gsl.gsl_matrix_alloc(rows, cols)
    return matrix

def extract_matrix(gsl_matrix):
    rows = gsl_matrix.size1
    cols = gsl_matrix.size2
    data = (ctypes.c_double * (rows * cols)).from_address(int(gsl_matrix.data))
    matrix = [[data[i * cols + j] for j in range(cols)] for i in range(rows)]
    return matrix

def apply_givens_qr(Q, R, i, j, c, s):
    M = len(Q)
    N = len(R[0])
    Q_cblas = create_gsl_matrix(M, N)
    for i in range(M * N):
        ctypes.c_double.from_address(int(Q_cblas.data) + 8 * i).value = Q[i // N][i % N]
    R_cblas = create_gsl_matrix(N, N)
    for i in range(N * N):
        ctypes.c_double.from_address(int(R_cblas.data) + 8 * i).value = R[i // N][i % N]
    gsl.apply_givens_qr(M, N, Q_cblas, R_cblas, i, j, c, s)
    for i in range(M):
        for j in range(N):
            Q[i][j] = ctypes.c_double.from_address(int(Q_cblas.data) + 8 * (i * N + j)).value
    for i in range(N):
        for j in range(N):
            R[i][j] = ctypes.c_double.from_address(int(R_cblas.data) + 8 * (i * N + j)).value
