class GSLSpMatrixInt:
    def __init__(self, data):
        self.rows = len(data)
        self.cols = len(data[0])
        self.nnz = sum(sum(1 for x in row if x != 0) for row in data)
        self.data_ptr = gsl.gsl_spmatrix_int_alloc(self.rows, self.cols, self.nnz)
        self.index_ptr = gsl.gsl_vector_int_alloc(self.nnz)
        self.value_ptr = gsl.gsl_vector_int_alloc(self.nnz)
        index_idx = 0
        value_idx = 0
        for i in range(self.rows):
            for j in range(self.cols):
                if data[i][j] != 0:
                    gsl.gsl_spmatrix_int_set_elem(self.data_ptr, i, j, data[i][j])
                    gsl.gsl_vector_int_set_elem(self.index_ptr, index_idx, i)
                    gsl.gsl_vector_int_set_elem(self.value_ptr, value_idx, j)
                    index_idx += 1
                    value_idx += 1

    def find_min_max(self):
        min_val = ctypes.c_int()
        max_val = ctypes.c_int()
        gsl.gsl_spmatrix_int_minmax(self.data_ptr, ctypes.byref(min_val), ctypes.byref(max_val))
        return (min_val.value, max_val.value)

    def __del__(self):
        gsl.gsl_spmatrix_int_free(self.data_ptr)
        gsl.gsl_vector_int_free(self.index_ptr)
        gsl.gsl_vector_int_free(self.value_ptr)

def find_min_max_in_sparse_matrix(matrix):
    sp_matrix = GSLSpMatrixInt(matrix)
