def cholesky_decomposition(input_matrix):
    rows, cols = len(input_matrix), len(input_matrix[0])
    matrix = gsl.gsl_matrix_float_alloc(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl.gsl_matrix_float_set(matrix, i, j, input_matrix[i][j])
    perm = gsl.gsl_permutation_alloc(rows)
    status = gsl.gsl_linalg_pcholesky_decomp(matrix, perm)
    if status != 0:
        raise Exception("Cholesky decomposition failed")
    result_matrix = [[gsl.gsl_matrix_float_get(matrix, i, j) for j in range(cols)] for i in range(rows)]
    permutation_vector = [gsl.gsl_permutation_get(perm, i) for i in range(rows)]
    gsl.gsl_permutation_free(perm)
    gsl.gsl_matrix_float_free(matrix)
    return result_matrix, permutation_vector

