    def __init__(self, data, rows, cols):
        self.rows = rows
        self.cols = cols
        self.data = (ctypes.c_double * (rows * cols))(*data)
        self.matrix = gsl.gsl_matrix_calloc(rows, cols)
        for i in range(rows):
            for j in range(cols):
                gsl.gsl_matrix_set(self.matrix, i, j, data[i * cols + j])

    def __del__(self):
        gsl.gsl_matrix_free(self.matrix)

