def create_histogram2d(nx, ny, xrange, yrange):
    if not isinstance(nx, int) or nx <= 0:
        raise ValueError('nx must be a positive integer')
    if not isinstance(ny, int) or ny <= 0:
        raise ValueError('ny must be a positive integer')
    if not all(isinstance(x, (int, float)) for x in xrange):
        raise ValueError('xrange must be a list of numbers')
    if not all(isinstance(y, (int, float)) for y in yrange):
        raise ValueError('yrange must be a list of numbers')
    if len(xrange) != nx + 1 or len(yrange) != ny + 1:
        raise ValueError('xrange and yrange must have lengths nx+1 and ny+1, respectively')
    if not all(xrange[i] < xrange[i + 1] for i in range(nx)):
        raise ValueError('xrange must be in increasing order')
    if not all(yrange[i] < yrange[i + 1] for i in range(ny)):
        raise ValueError('yrange must be in increasing order')

    xrange_array = (ctypes.c_double * (nx + 1))(*xrange)
    yrange_array = (ctypes.c_double * (ny + 1))(*yrange)
    histogram = gsl_create_histogram2d(nx, ny, ctypes.byref(xrange_array), ctypes.byref(yrange_array))

    if not histogram:
        raise RuntimeError('Failed to allocate memory for gsl_histogram2d')

